  "firstMeeting.fallback": "Так это вы меня разбудили. Рада сотрудничеству.",
  "firstMeeting.rexia": "Я — королева битвы.",
  "firstMeeting.torika": "Капитан, держитесь за мной. Впереди прикрою я!",
  "firstMeeting.spina": "…Я Спина. Где слышен шум воды — туда я и пойду следом.",
  "firstMeeting.luka": "Исследователь? Если не срочно, я ещё немного полежу.",
  "firstMeeting.dodi": "Капитан, гляди! Открытие века!",
  "firstMeeting.tia": "Исследователь, видите, что там блестит? Можно я подберу?",
  "firstMeeting.stella": "Приятно познакомиться, сэмпай! Сегодняшние воздушные потоки я уже все прочитала.",
  "firstMeeting.meron": "Я Мерон… Хочу вас нарисовать. Можно посмотреть на ваше лицо?",
  "firstMeeting.pachi": "Эй, посторонись! Расчищаю путь боссу.",
  "firstMeeting.maki": "Сначала диагноз, мяу. Выгляжу так, но я врач, мяу!",
  "firstMeeting.keris": "Сэмпай, ищете книгу? Я покажу, где она.",
  "firstMeeting.delopi": "Та-дам! Вот ваш ключ, исследователь.",
  "firstMeeting.nodonia": "Скажи, когда будет больно, малыш. Я приму удар за тебя.",
  "firstMeeting.ella": "Я удержу позицию. Тыл за мной.",
  "firstMeeting.mette": "Сцена только для тебя начинается сейчас.",
  "firstMeeting.dei": "Я Дей! Эта стена ещё совсем пустая? Можно на ней порисовать?",
  "firstMeeting.maddy": "Я Мэдди, Исследователь. Здесь жарковато. Можно усилить охлаждение?",
  "firstMeeting.terisa": "Если где-то порвётся, скажите… я зашью, исследователь.",
  "firstMeeting.parua": "Далеко… так далеко! Мне всё видно.",
  "firstMeeting.shute": "Говорю же, не то! Слушай мои команды, я затащу.",
  "firstMeeting.morphe": "…Куратор? Хорошо, что ты здесь. Подожди… Выведу экран.",
  "firstMeeting.dian": "Капитана защищу я! …Ой, Куро! Широ! Ко мне!",
