  "relic.viria.origin": "Соня",
  "relic.viria.excavationSite": "Отложения карстовой пещеры, Словения",
  "relic.viria.fossilRecord": "Из одного слоя пещерных отложений извлекли десятки черепов одного вида. Пять из них так совпадают по размеру и зубам, что их отнесли к одному помёту.",
  "relic.viria.catalogSummary": "Образец на основе сони с увеличенными резцами и защёчными мешками.",
  "relic.viria.squadNote": "Расходная масса Истребления. Они разом текут туда, куда укажут, заполняя коридор, и задние шагают прямо через место, где пали передние.",
  "relic.viria.researcherTitle": "Исследователь",
  "relic.viria.unlockRecord": "Запись об идентификации 207. Подтверждена принадлежность к Истреблению. Из пяти в капюшонных пижамах с мышиными ушками это — с зелёным узлом; бросаются в глаза сумочка в форме сыра, тапочки с зубами и полосатый хвост с лентой на конце. Найдя еду, оно подавало знак не писком, а звуком резцов, и услышавшие сёстры разом сбегались в одно место. Там, где оно грызло, оставались рассыпанные свежие ростки, а в каждом следе на его пути прорастали семена, и за ним тянулась зелёная тропа. Почему оно не перестаёт есть даже в пору спячки, не подтверждено.",
  "relic.viria.observation.originYear": "Около 2 млн лет назад",
  "relic.viria.observation.restorationYear": "E.C. 2",
  "relic.viria.observation.lifeStage": "Юная",
  "relic.viria.observation.height": "0,94 м",
  "relic.viria.observation.weight": "21 кг",
  "relic.viria.passive.name": "Спячка",
  "relic.viria.passive.desc": "Раз за бой, когда ОЗ падают до половины или ниже, 5 секунд восстанавливает по 3% макс. ОЗ в секунду.",
  "relic.viria.ferocity.name": "Обжорство",
  "relic.viria.basic.name": "Грызь резцами",
  "relic.viria.ultimate.name": "Опустошение защёчных мешков",
  "relic.viria.projectName": "ANNIHILATION SWARM — Перекормленная популяция",
  "relic.guttia.name": "Гуттия",
  "relic.guttia.origin": "Соня",
  "relic.guttia.excavationSite": "Отложения карстовой пещеры, Словения",
  "relic.guttia.fossilRecord": "Из одного слоя пещерных отложений извлекли десятки черепов одного вида. Пять из них так совпадают по размеру и зубам, что их отнесли к одному помёту.",
  "relic.guttia.catalogSummary": "Образец на основе сони с увеличенными резцами и защёчными мешками.",
  "relic.guttia.squadNote": "Расходная масса Истребления. Они разом текут туда, куда укажут, заполняя коридор, и задние шагают прямо через место, где пали передние.",
  "relic.guttia.researcherTitle": "Исследователь",
  "relic.guttia.unlockRecord": "Запись об идентификации 208. Подтверждена принадлежность к Истреблению. Среди таких же капюшонных пижам это — с голубым полосатым хвостом и ватным комком на конце; улыбается, одна рука на поясе, пальцы другой у уголка рта. Услышав стук резцов сестры, она с улыбкой выбегала первой, а приблизившись, прежде всего грызла резцами то снаряжение, что оказывалось под рукой. Там, где прошла стая, тянулась длинная цепочка мокрых следов. Что смачивает эти следы, не подтверждено.",
  "relic.guttia.observation.originYear": "Около 2 млн лет назад",
  "relic.guttia.observation.restorationYear": "E.C. 2",
  "relic.guttia.observation.lifeStage": "Юная",
  "relic.guttia.observation.height": "0,94 м",
  "relic.guttia.observation.weight": "21 кг",
  "relic.guttia.passive.name": "Спячка",
  "relic.guttia.passive.desc": "Раз за бой, когда ОЗ падают до половины или ниже, 5 секунд восстанавливает по 3% макс. ОЗ в секунду.",
  "relic.guttia.ferocity.name": "Обжорство",
  "relic.guttia.basic.name": "Грызь резцами",
  "relic.guttia.ultimate.name": "Опустошение защёчных мешков",
  "relic.guttia.projectName": "ANNIHILATION SWARM — Перекормленная популяция",
  "relic.favia.name": "Фавия",
  "relic.favia.origin": "Соня",
  "relic.favia.excavationSite": "Отложения карстовой пещеры, Словения",
  "relic.favia.fossilRecord": "Из одного слоя пещерных отложений извлекли десятки черепов одного вида. Пять из них так совпадают по размеру и зубам, что их отнесли к одному помёту.",
  "relic.favia.catalogSummary": "Образец на основе сони с увеличенными резцами и защёчными мешками.",
  "relic.favia.squadNote": "Расходная масса Истребления. Они разом текут туда, куда укажут, заполняя коридор, и задние шагают прямо через место, где пали передние.",
  "relic.favia.researcherTitle": "Исследователь",
  "relic.favia.unlockRecord": "Запись об идентификации 209. Подтверждена принадлежность к Истреблению. Среди таких же капюшонных пижам это — с розовым клетчатым бантом; стоит с не до конца проснувшимся лицом, одной рукой трёт глаза, другая на поясе. Несмотря на сонный вид, оно не переставало есть и продолжало грызть резцами, даже когда защёчные мешки были полны. Когда сёстры бросались вперёд, оно шло следом, протирая глаза. Сонливость это притворство или настоящая, не подтверждено.",
  "relic.favia.observation.originYear": "Около 2 млн лет назад",
  "relic.favia.observation.restorationYear": "E.C. 2",
  "relic.favia.observation.lifeStage": "Юная",
  "relic.favia.observation.height": "0,94 м",
  "relic.favia.observation.weight": "21 кг",
  "relic.favia.passive.name": "Спячка",
  "relic.favia.passive.desc": "Раз за бой, когда ОЗ падают до половины или ниже, 5 секунд восстанавливает по 3% макс. ОЗ в секунду.",
  "relic.favia.ferocity.name": "Обжорство",
  "relic.favia.basic.name": "Грызь резцами",
  "relic.favia.ultimate.name": "Опустошение защёчных мешков",
