  "relic.silia.name": "Силия",
  "relic.silia.origin": "Соня",
  "relic.silia.excavationSite": "Отложения карстовой пещеры, Словения",
  "relic.silia.fossilRecord": "Из одного слоя пещерных отложений извлекли десятки черепов одного вида. Пять из них так совпадают по размеру и зубам, что их отнесли к одному помёту.",
  "relic.silia.catalogSummary": "Образец на основе сони с увеличенными резцами и защёчными мешками.",
  "relic.silia.squadNote": "Расходная масса Истребления. Они разом текут туда, куда укажут, заполняя коридор, и задние шагают прямо через место, где пали передние.",
  "relic.silia.researcherTitle": "Исследователь",
  "relic.silia.unlockRecord": "Запись об идентификации 210. Подтверждена принадлежность к Истреблению. Среди таких же капюшонных пижам это бросается в глаза коричневой основой, жёлтым узлом и заплетённой косой; на кончике хвоста — большой пушистый ком. Когда оно стояло, вытянув руки вперёд, сёстры разом текли в сторону его кончиков пальцев, а там, где падала передняя, задняя просто перешагивала через неё. Кто определяет, куда указывают его пальцы, не подтверждено.",
  "relic.silia.observation.originYear": "Около 2 млн лет назад",
  "relic.silia.observation.restorationYear": "E.C. 2",
  "relic.silia.observation.lifeStage": "Юная",
  "relic.silia.observation.height": "0,94 м",
  "relic.silia.observation.weight": "21 кг",
  "relic.silia.passive.name": "Спячка",
  "relic.silia.passive.desc": "Раз за бой, когда ОЗ падают до половины или ниже, 5 секунд восстанавливает по 3% макс. ОЗ в секунду.",
  "relic.silia.ferocity.name": "Обжорство",
  "relic.silia.basic.name": "Грызь резцами",
  "relic.silia.ultimate.name": "Опустошение защёчных мешков",
