  "relic.ventia.name": "Вентия",
  "relic.ventia.origin": "Соня",
  "relic.ventia.excavationSite": "Отложения карстовой пещеры, Словения",
  "relic.ventia.fossilRecord": "Из одного слоя пещерных отложений извлекли десятки черепов одного вида. Пять из них так совпадают по размеру и зубам, что их отнесли к одному помёту.",
  "relic.ventia.catalogSummary": "Образец на основе сони с увеличенными резцами и защёчными мешками.",
  "relic.ventia.squadNote": "Расходная масса Истребления. Они разом текут туда, куда укажут, заполняя коридор, и задние шагают прямо через место, где пали передние.",
  "relic.ventia.researcherTitle": "Исследователь",
  "relic.ventia.unlockRecord": "Запись опознания 211. Подтверждена принадлежность к «Истреблению». Это особь с мятным бантом среди сестёр в одинаковых пижамах с капюшоном; стоит, скрестив руки и плотно сжав губы. Она нехотя пошла следом лишь после того, как сёстры бросились к еде, но, добравшись, дольше всех работала резцами. Ни разу не удалось зафиксировать, чтобы она подавала резцами какой-либо сигнал.",
  "relic.ventia.observation.originYear": "Около 2 млн лет назад",
  "relic.ventia.observation.restorationYear": "E.C. 2",
